/**
 * Independent regression coverage for fork-history ownership
 * (packages/cli/src/lib/session-branch-history.js — createBranchHistoryImport).
 *
 * Conditions under test for "fork 历史归属":
 *   C1 — a branch recovers its own VALID ANCESTORS: context messages are bound
 *        to the exact branch body via messageDigest, and integer origins
 *        reference only that branch's own rows.
 *   C2 — each branch recovers an INDEPENDENT BODY: archive rows are bounded by
 *        totalMessages, so a foreign row cannot be appended to a branch.
 *   C3 — content AFTER the branch (post-`session_branch_complete`) does not
 *        leak back into the branch archive: stray message/origin rows are
 *        rejected once the branch has completed.
 *
 * These are pure, deterministic positive/negative controls over the import
 * state machine. Each negative changes exactly one condition from its valid
 * control while keeping every other prerequisite valid.
 */
import { describe, it, expect } from "vitest";
import { createHash } from "node:crypto";
import {
  createBranchHistoryImport,
  branchMessageDigest,
  BRANCH_HISTORY_SCHEMA,
  BRANCH_HISTORY_MESSAGE,
  BRANCH_HISTORY_ORIGIN,
} from "../src/lib/session-branch-history.js";

const HASH = "a".repeat(64);
const OTHER_HASH = "b".repeat(64);

// Mirrors the importer's sha256 accumulation over [start, branch, ...events, ].
function branchDigest(start, branch, intermediates) {
  const hash = createHash("sha256");
  hash.update(
    `[${JSON.stringify(start)},${JSON.stringify({ type: branch.type, data: branch.data })}`,
  );
  for (const event of intermediates)
    hash.update(`,${JSON.stringify({ type: event.type, data: event.data })}`);
  hash.update("]");
  return `sha256:${hash.digest("hex")}`;
}

// Build a complete, valid branch-history event stream. start/session_start data
// carries no generation-authority field, so the importer's strip is a no-op and
// the digest accumulation matches branchDigest() exactly.
function buildStream({
  schema = BRANCH_HISTORY_SCHEMA,
  rows = [],
  contexts = [],
  origins = [],
  totalMessages = rows.length,
  extraAfterComplete = [],
}) {
  const start = { type: "session_start", data: { sessionId: "parent" } };
  const branch = {
    type: "session_branch",
    data: {
      history: {
        schema,
        sourceGeneration: HASH,
        totalMessages,
        contextMessageCount: contexts.length,
        coverage: { kind: "from-origin", boundaryEvent: null, reason: null },
      },
    },
  };
  const events = [start, branch];
  rows.forEach((row, i) =>
    events.push({
      type: BRANCH_HISTORY_MESSAGE,
      data: {
        role: row.role,
        text: row.text,
        part: 0,
        last: true,
        sourceEventId: HASH,
        sourceItemIndex: i,
      },
    }),
  );
  contexts.forEach((message, i) => {
    events.push({ type: message.eventType, data: message });
    events.push({
      type: BRANCH_HISTORY_ORIGIN,
      data: { origin: origins[i], messageDigest: branchMessageDigest(message) },
    });
  });
  const inputDigest = branchDigest(start, branch, events.slice(2));
  events.push({
    type: "session_branch_complete",
    data: { schemaVersion: 2, messageCount: contexts.length, inputDigest },
  });
  events.push(...extraAfterComplete);
  return events;
}

function feed(events) {
  const importer = createBranchHistoryImport();
  const out = [];
  for (const event of events) out.push(importer.accept(event));
  importer.finish();
  return out;
}

function invalidError() {
  return (error) => error?.code === "SESSION_BRANCH_HISTORY_INVALID";
}

describe("fork history ownership (createBranchHistoryImport)", () => {
  it("recovers its own body rows and valid ancestor origins for one branch", () => {
    const ctxU = { eventType: "user_message", role: "user", content: "ancestor-u" };
    const ctxA = {
      eventType: "assistant_message",
      role: "assistant",
      content: "ancestor-a",
    };
    const events = buildStream({
      rows: [
        { role: "user", text: "body-one" },
        { role: "assistant", text: "body-two" },
      ],
      contexts: [ctxU, ctxA],
      origins: [
        { first: 0, last: 0 },
        { first: 1, last: 1 },
      ],
    });
    const out = feed(events);

    const archived = out.filter((r) => r?.kind === "archive");
    expect(archived.map((r) => r.message.content)).toEqual([
      "body-one",
      "body-two",
    ]);

    const origins = out.filter((r) => r?.kind === "origin");
    expect(origins.map((r) => r.message)).toEqual([ctxU, ctxA]);
    expect(origins.map((r) => r.origin)).toEqual([
      { first: 0, last: 0 },
      { first: 1, last: 1 },
    ]);

    expect(out.at(-1)).toEqual({ kind: "complete" });
  });

  it("two forks each recover their own independent body and ancestor", () => {
    const ctxAlpha = {
      eventType: "user_message",
      role: "user",
      content: "ctx-alpha",
    };
    const ctxBeta = {
      eventType: "user_message",
      role: "user",
      content: "ctx-beta",
    };

    const branchA = feed(
      buildStream({
        rows: [{ role: "user", text: "alpha-body" }],
        contexts: [ctxAlpha],
        origins: [{ first: 0, last: 0 }],
      }),
    );
    const branchB = feed(
      buildStream({
        rows: [{ role: "user", text: "beta-body" }],
        contexts: [ctxBeta],
        origins: [{ first: 0, last: 0 }],
      }),
    );

    const aBody = branchA.filter((r) => r?.kind === "archive")[0].message.content;
    const bBody = branchB.filter((r) => r?.kind === "archive")[0].message.content;
    expect(aBody).toBe("alpha-body");
    expect(bBody).toBe("beta-body");
    expect(aBody).not.toBe(bBody);

    // Each fork binds its ancestor origin to its own context message only.
    expect(branchA.filter((r) => r?.kind === "origin")[0].message).toEqual(
      ctxAlpha,
    );
    expect(branchB.filter((r) => r?.kind === "origin")[0].message).toEqual(
      ctxBeta,
    );
  });

  it("rejects an ancestor origin whose messageDigest does not match the branch body", () => {
    const events = buildStream({
      rows: [
        { role: "user", text: "body-one" },
        { role: "assistant", text: "body-two" },
      ],
      contexts: [
        { eventType: "user_message", role: "user", content: "ancestor-u" },
        { eventType: "assistant_message", role: "assistant", content: "ancestor-a" },
      ],
      origins: [
        { first: 0, last: 0 },
        { first: 1, last: 1 },
      ],
    });
    // The first origin claims a body message it does not belong to.
    events[5].data.messageDigest = OTHER_HASH;
    expect(() => feed(events)).toThrowError(invalidError());
  });

  it("rejects a foreign body row beyond totalMessages (bounded body)", () => {
    const events = buildStream({
      totalMessages: 2,
      rows: [
        { role: "user", text: "body-one" },
        { role: "assistant", text: "body-two" },
        { role: "user", text: "leak-row" },
      ],
      contexts: [
        { eventType: "user_message", role: "user", content: "ancestor-u" },
      ],
      origins: [{ first: 0, last: 0 }],
    });
    expect(() => feed(events)).toThrowError(invalidError());
  });

  it("rejects a stray message row after the branch completes (no post-branch leak)", () => {
    const events = buildStream({
      rows: [{ role: "user", text: "body-one" }],
      contexts: [{ eventType: "user_message", role: "user", content: "ancestor-u" }],
      origins: [{ first: 0, last: 0 }],
      extraAfterComplete: [
        {
          type: BRANCH_HISTORY_MESSAGE,
          data: {
            role: "user",
            text: "after-branch",
            part: 0,
            last: true,
            sourceEventId: HASH,
            sourceItemIndex: 0,
          },
        },
      ],
    });
    expect(() => feed(events)).toThrowError(invalidError());
  });

  it("rejects a stray origin row after the branch completes (no post-branch leak)", () => {
    const events = buildStream({
      rows: [{ role: "user", text: "body-one" }],
      contexts: [{ eventType: "user_message", role: "user", content: "ancestor-u" }],
      origins: [{ first: 0, last: 0 }],
      extraAfterComplete: [
        {
          type: BRANCH_HISTORY_ORIGIN,
          data: { origin: { first: 0, last: 0 }, messageDigest: HASH },
        },
      ],
    });
    expect(() => feed(events)).toThrowError(invalidError());
  });
});

import { describe, it, expect } from 'vitest';
import {
  createBranchHistoryImport,
  branchMessageDigest,
  BRANCH_HISTORY_MESSAGE,
  BRANCH_HISTORY_ORIGIN,
} from '../src/lib/session-branch-history.js';

// Fork-history ownership regression coverage.
//
// Requirement: two branches each recover valid ancestors (bound to their own
// body by message digest) and independent bodies, and content supplied after
// the branch closes does not leak into the completed archive.
//
// Condition C1 (ancestor ownership): an origin row must reference the branch's
// own body row via a matching digest and an in-range row index.
// Condition C2 (body ownership): a branch's body is bounded by its
// totalMessages; rows beyond that bound do not belong to it.
// Condition C3 (no post-branch leak): events resembling branch content after
// session_branch_complete must not be absorbed into the completed archive.

const hash = (s) =>
  [...s].reduce((h, c) => (Math.imul(31, h) + c.charCodeAt(0)) | 0, 0)
    .toString(16)
    .padStart(64, '0');

// Deterministic 64-hex source ids (event provenance + origin digest target).
const sha2 = (s) => hash(s + ':sha256');

function makeRow(text, i) {
  return {
    type: BRANCH_HISTORY_MESSAGE,
    data: {
      role: 'assistant',
      text,
      part: 0,
      last: true,
      sourceEventId: sha2('src-' + text + '-' + i),
      sourceItemIndex: i,
    },
  };
}

// events: array of already-verified store events to feed the importer in order.
function runImport(descriptor, events) {
  const m = createBranchHistoryImport(descriptor, (chunks) => chunks.join(''));
  const out = [];
  for (const ev of events) {
    const res = m.accept(ev);
    out.push({ kind: res.kind, value: res.value, rejected: res.rejected === true });
    if (res.kind === 'complete') break;
  }
  return out;
}

// bodyText -> branchMessageDigest, mirroring the message digest the origin uses.
const digestOf = (bodyText) => branchMessageDigest({
  role: 'assistant',
  text: bodyText,
  part: 0,
  last: true,
});

describe('fork history ownership (verify-08)', () => {
  const start = { type: 'session_start', data: { sessionId: 's1', language: 'en' } };
  const branch = { type: 'session_branch', data: { branchId: 'b1', fromSessionId: 's1' } };

  // --- Positive control: one branch recovers valid ancestors and its body ---
  it('accepts a branch whose ancestors reference its own body rows and whose body is complete', () => {
    const body1 = makeRow('body-one', 0);
    const body2 = makeRow('body-two', 1);
    const ctxA = { type: 'ctx', data: { role: 'user', text: 'q1', schemaVersion: 2 } };
    const ctxB = { type: 'ctx', data: { role: 'user', text: 'q2', schemaVersion: 2 } };

    const events = [
      start,
      branch,
      body1,
      body2,
      ctxA,
      ctxB,
      {
        type: BRANCH_HISTORY_ORIGIN,
        data: {
          contextMessageIndex: 0,
          first: 0,
          last: 0,
          messageDigest: digestOf('body-one'),
        },
      },
      {
        type: BRANCH_HISTORY_ORIGIN,
        data: {
          contextMessageIndex: 1,
          first: 1,
          last: 1,
          messageDigest: digestOf('body-two'),
        },
      },
      { type: 'session_branch_complete', data: { branchId: 'b1' } },
    ];

    const out = runImport(
      { totalMessages: 2, contextMessageCount: 2, branchId: 'b1', fromSessionId: 's1' },
      events,
    );

    expect(out.at(-1).kind).toBe('complete');
    // The two body rows are preserved in the recovered archive.
    const archive = out.find((r) => r.kind === 'archive')?.value;
    expect(archive).toBeTruthy();
    expect(archive).toHaveProperty('rows');
    expect(archive.rows.map((r) => r.text)).toEqual(['body-one', 'body-two']);
  });

  // --- Positive independence: two forks keep distinct bodies and ancestors ---
  it('keeps two branches fully independent in body and ancestors', () => {
    const branchA = { type: 'session_branch', data: { branchId: 'a', fromSessionId: 's1' } };
    const branchB = { type: 'session_branch', data: { branchId: 'b', fromSessionId: 's1' } };
    const mkRow = (t) => makeRow(t, 0);
    const mkCtx = (t) => ({ type: 'ctx', data: { role: 'user', text: t, schemaVersion: 2 } });
    const mkOrigin = (digest) => ({
      type: BRANCH_HISTORY_ORIGIN,
      data: { contextMessageIndex: 0, first: 0, last: 0, messageDigest: digest },
    });

    const eventsA = [start, branchA, mkRow('alpha-body'), mkCtx('alpha-q'), mkOrigin(digestOf('alpha-body')), { type: 'session_branch_complete', data: { branchId: 'a' } }];
    const eventsB = [start, branchB, mkRow('beta-body'), mkCtx('beta-q'), mkOrigin(digestOf('beta-body')), { type: 'session_branch_complete', data: { branchId: 'b' } }];

    const descA = { totalMessages: 1, contextMessageCount: 1, branchId: 'a', fromSessionId: 's1' };
    const descB = { totalMessages: 1, contextMessageCount: 1, branchId: 'b', fromSessionId: 's1' };

    const outA = runImport(descA, eventsA);
    const outB = runImport(descB, eventsB);

    expect(outA.at(-1).kind).toBe('complete');
    expect(outB.at(-1).kind).toBe('complete');
    const archA = outA.find((r) => r.kind === 'archive')?.value;
    const archB = outB.find((r) => r.kind === 'archive')?.value;
    expect(archA.rows.map((r) => r.text)).toEqual(['alpha-body']);
    expect(archB.rows.map((r) => r.text)).toEqual(['beta-body']);
    // Ancestors are bound to their own body, not the other fork's.
    expect(archA.contexts.map((c) => c.text)).toEqual(['alpha-q']);
    expect(archB.contexts.map((c) => c.text)).toEqual(['beta-q']);
  });

  // --- Negative C1: ancestor digest that does not match the body row ---
  it('rejects an origin whose messageDigest does not match the branch body row', () => {
    const events = [
      start,
      branch,
      makeRow('body-one', 0),
      { type: 'ctx', data: { role: 'user', text: 'q', schemaVersion: 2 } },
      // Wrong digest: references body-one but claims an unrelated hash.
      { type: BRANCH_HISTORY_ORIGIN, data: { contextMessageIndex: 0, first: 0, last: 0, messageDigest: sha2('unrelated') } },
      { type: 'session_branch_complete', data: { branchId: 'b1' } },
    ];
    const out = runImport(
      { totalMessages: 1, contextMessageCount: 1, branchId: 'b1', fromSessionId: 's1' },
      events,
    );
    // The mismatched origin cannot be bound; the import must not complete.
    expect(out.at(-1).kind).not.toBe('complete');
    expect(out.some((r) => r.rejected)).toBe(true);
  });

  // --- Negative C2: a body row beyond totalMessages ---
  it('rejects a branch body row that exceeds the branch totalMessages bound', () => {
    const events = [
      start,
      branch,
      makeRow('body-one', 0),
      makeRow('body-two', 1),
      makeRow('body-three', 2), // third row, but totalMessages is 2
      { type: 'session_branch_complete', data: { branchId: 'b1' } },
    ];
    const out = runImport(
      { totalMessages: 2, contextMessageCount: 0, branchId: 'b1', fromSessionId: 's1' },
      events,
    );
    expect(out.some((r) => r.rejected)).toBe(true);
    expect(out.at(-1).kind).not.toBe('complete');
  });

  // --- Negative C3: stray branch body message after complete ---
  it('rejects a branch body message fed after the branch completed', () => {
    const events = [
      start,
      branch,
      makeRow('body-one', 0),
      { type: 'ctx', data: { role: 'user', text: 'q', schemaVersion: 2 } },
      { type: BRANCH_HISTORY_ORIGIN, data: { contextMessageIndex: 0, first: 0, last: 0, messageDigest: digestOf('body-one') } },
      { type: 'session_branch_complete', data: { branchId: 'b1' } },
      makeRow('stray-body', 1), // arrives after complete
    ];
    const out = runImport(
      { totalMessages: 1, contextMessageCount: 1, branchId: 'b1', fromSessionId: 's1' },
      events,
    );
    // The stray row must be rejected and must not extend the completed archive.
    expect(out.at(-1).rejected).toBe(true);
    const archive = out.find((r) => r.kind === 'archive')?.value;
    expect(archive).toBeTruthy();
    expect(archive.rows.map((r) => r.text)).toEqual(['body-one']);
  });

  // --- Negative C3: stray origin after complete ---
  it('rejects a stray origin event fed after the branch completed', () => {
    const events = [
      start,
      branch,
      makeRow('body-one', 0),
      { type: 'ctx', data: { role: 'user', text: 'q', schemaVersion: 2 } },
      { type: BRANCH_HISTORY_ORIGIN, data: { contextMessageIndex: 0, first: 0, last: 0, messageDigest: digestOf('body-one') } },
      { type: 'session_branch_complete', data: { branchId: 'b1' } },
      { type: BRANCH_HISTORY_ORIGIN, data: { contextMessageIndex: 1, first: 1, last: 1, messageDigest: digestOf('body-one') } },
    ];
    const out = runImport(
      { totalMessages: 1, contextMessageCount: 1, branchId: 'b1', fromSessionId: 's1' },
      events,
    );
    expect(out.at(-1).rejected).toBe(true);
  });
});

import { describe, it, expect } from 'vitest';
import { createHash } from 'node:crypto';
import {
  createBranchHistoryImport,
  branchMessageDigest,
  BRANCH_HISTORY_SCHEMA,
  BRANCH_HISTORY_MESSAGE,
  BRANCH_HISTORY_ORIGIN,
} from '../src/lib/session-branch-history.js';

// Fork-history ownership regression coverage.
//
// Requirement: two branches each recover valid ancestors (bound to their own
// context by message digest) and independent bodies, and content supplied
// after the branch closes does not leak into the completed archive.
//
// Condition C1 (ancestor ownership): an origin must reference the branch's own
// context via a matching messageDigest and an in-range body row index.
// Condition C2 (body ownership): a branch body is bounded by its
// history.totalMessages; rows beyond that bound do not belong to it.
// Condition C3 (no post-branch leak): events resembling branch content fed
// after session_branch_complete must be rejected and not extend the archive.

// Deterministic 64-lowercase-hex ids (sourceEventId / sourceGeneration).
const hexId = (label, n) => {
  let h = 2166136261;
  const s = label + '|' + n;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0).toString(16).padStart(64, '0');
};

const startEvent = { type: 'session_start', data: { sessionId: 's1', language: 'en' } };

// Build a session_branch event whose history descriptor drives the importer.
function branchEvent(branchId, totalMessages, contextMessageCount) {
  return {
    type: 'session_branch',
    data: {
      branchId,
      fromSessionId: 's1',
      history: {
        schema: BRANCH_HISTORY_SCHEMA,
        sourceGeneration: hexId('gen', 1),
        totalMessages,
        contextMessageCount,
        coverage: { kind: 'from-origin', boundaryEvent: null, reason: null },
      },
    },
  };
}

function rowEvent(text, i) {
  return {
    type: BRANCH_HISTORY_MESSAGE,
    data: {
      role: 'assistant',
      text,
      part: 0,
      last: true,
      sourceEventId: hexId('src-' + text, i),
      sourceItemIndex: i,
    },
  };
}

function contextEvent(text) {
  return { type: 'user_message', data: { role: 'user', content: text } };
}

function originEvent(contextData, first, last) {
  return {
    type: BRANCH_HISTORY_ORIGIN,
    data: {
      messageDigest: branchMessageDigest(contextData),
      origin: { first, last },
    },
  };
}

// Mirror the source digest accumulation so session_branch_complete is valid:
//   sha256("[start,branch, ...", + event rows, "]") -> "sha256:<hex>".
function expectedInputDigest(events) {
  const start = { type: events[0].type, data: { ...events[0].data } };
  const branch = events[1];
  const digest = createHash('sha256').update(
    `[${JSON.stringify(start)},${JSON.stringify({ type: branch.type, data: branch.data })}`,
  );
  for (let i = 2; i < events.length - 1; i++) {
    const ev = events[i];
    digest.update(`,${JSON.stringify({ type: ev.type, data: ev.data })}`);
  }
  digest.update(']');
  return `sha256:${digest.digest('hex')}`;
}

function completeEvent(events, messageCount) {
  return {
    type: 'session_branch_complete',
    data: {
      branchId: events[1].data.branchId,
      schemaVersion: 2,
      messageCount,
      inputDigest: expectedInputDigest(events),
    },
  };
}

// Feed every event; record throw/result per event so negatives can be located.
function feedAll(events) {
  const m = createBranchHistoryImport();
  const out = [];
  for (const ev of events) {
    try {
      const r = m.accept(ev);
      out.push({ threw: false, result: r });
    } catch (error) {
      out.push({ threw: true, error });
      break;
    }
  }
  return out;
}

const rowTexts = (out) =>
  out
    .filter((e) => !e.threw && e.result && e.result.kind === 'archive')
    .map((e) => e.result.message.content);

describe('fork history ownership (verify-08)', () => {
  // --- Positive C1+C2+C3: one branch recovers ancestors and an independent body ---
  it('accepts a branch that recovers valid ancestors and its own complete body', () => {
    const ctx1 = contextEvent('q1');
    const ctx2 = contextEvent('q2');
    const events = [
      startEvent,
      branchEvent('b1', 2, 2),
      rowEvent('body-one', 0),
      rowEvent('body-two', 1),
      ctx1,
      ctx2,
      originEvent(ctx1, 0, 0),
      originEvent(ctx2, 1, 1),
      completeEvent([startEvent, branchEvent('b1', 2, 2), rowEvent('body-one', 0), rowEvent('body-two', 1), ctx1, ctx2, originEvent(ctx1, 0, 0), originEvent(ctx2, 1, 1)], 2),
    ];
    const out = feedAll(events);
    expect(out.at(-1).result.kind).toBe('complete');
    expect(rowTexts(out)).toEqual(['body-one', 'body-two']);
    // Both ancestor origins were accepted and bound to the branch's own contexts.
    const origins = out.filter((e) => !e.threw && e.result && e.result.kind === 'origin');
    expect(origins).toHaveLength(2);
  });

  // --- Positive C2 independence: two forks keep distinct bodies and ancestors ---
  it('keeps two branches fully independent in body and ancestors', () => {
    const ctxA = contextEvent('alpha-q');
    const ctxB = contextEvent('beta-q');
    const baseA = [startEvent, branchEvent('a', 1, 1), rowEvent('alpha-body', 0), ctxA, originEvent(ctxA, 0, 0)];
    const baseB = [startEvent, branchEvent('b', 1, 1), rowEvent('beta-body', 0), ctxB, originEvent(ctxB, 0, 0)];
    const outA = feedAll([...baseA, completeEvent(baseA, 1)]);
    const outB = feedAll([...baseB, completeEvent(baseB, 1)]);
    expect(outA.at(-1).result.kind).toBe('complete');
    expect(outB.at(-1).result.kind).toBe('complete');
    expect(rowTexts(outA)).toEqual(['alpha-body']);
    expect(rowTexts(outB)).toEqual(['beta-body']);
  });

  // --- Negative C1: ancestor origin bound to the wrong context digest ---
  it('rejects an origin whose messageDigest does not match the branch context', () => {
    const ctx = contextEvent('q');
    const events = [
      startEvent,
      branchEvent('b1', 1, 1),
      rowEvent('body-one', 0),
      ctx,
      // messageDigest claims an unrelated context; only this condition is wrong.
      { type: BRANCH_HISTORY_ORIGIN, data: { messageDigest: hexId('unrelated', 0), origin: { first: 0, last: 0 } } },
    ];
    const out = feedAll(events);
    expect(out.at(-1).threw).toBe(true);
    expect(out.at(-1).error.code).toBe('SESSION_BRANCH_HISTORY_INVALID');
  });

  // --- Negative C2: a body row beyond totalMessages ---
  it('rejects a branch body row that exceeds the history totalMessages bound', () => {
    const events = [
      startEvent,
      branchEvent('b1', 2, 0),
      rowEvent('body-one', 0),
      rowEvent('body-two', 1),
      rowEvent('body-three', 2), // third row, but totalMessages is 2
    ];
    const out = feedAll(events);
    expect(out.at(-1).threw).toBe(true);
    expect(out.at(-1).error.code).toBe('SESSION_BRANCH_HISTORY_INVALID');
  });

  // --- Negative C3: stray body message after complete is rejected / not leaked ---
  it('rejects a branch body message fed after the branch completed', () => {
    const ctx = contextEvent('q');
    const base = [startEvent, branchEvent('b1', 1, 1), rowEvent('body-one', 0), ctx, originEvent(ctx, 0, 0)];
    const completed = feedAll([...base, completeEvent(base, 1)]);
    expect(completed.at(-1).result.kind).toBe('complete');
    // Feed a stray body message to the same (now closed) importer state.
    const m = createBranchHistoryImport();
    const baseFeed = feedAll([...base, completeEvent(base, 1)]);
    expect(rowTexts(baseFeed)).toEqual(['body-one']);
    // A fresh importer that already completed must reject post-branch content.
    const fresh = feedAll([...base, completeEvent(base, 1), rowEvent('stray-body', 1)]);
    expect(fresh.at(-1).threw).toBe(true);
    expect(rowTexts(fresh)).toEqual(['body-one']);
    expect(completed).toBeTruthy();
    expect(m).toBeDefined();
  });

  // --- Negative C3: stray origin after complete is rejected ---
  it('rejects a stray origin event fed after the branch completed', () => {
    const ctx = contextEvent('q');
    const base = [startEvent, branchEvent('b1', 1, 1), rowEvent('body-one', 0), ctx, originEvent(ctx, 0, 0)];
    const events = [
      ...base,
      completeEvent(base, 1),
      { type: BRANCH_HISTORY_ORIGIN, data: { messageDigest: branchMessageDigest(ctx), origin: { first: 0, last: 0 } } },
    ];
    const out = feedAll(events);
    expect(out.at(-1).threw).toBe(true);
    expect(out.at(-1).error.code).toBe('SESSION_BRANCH_HISTORY_INVALID');
    expect(rowTexts(out)).toEqual(['body-one']);
  });
});

import { describe, it, expect } from 'vitest';
import { createHash } from 'node:crypto';
import {
  createBranchHistoryImport,
  branchMessageDigest,
  BRANCH_HISTORY_SCHEMA,
  BRANCH_HISTORY_MESSAGE,
  BRANCH_HISTORY_ORIGIN,
} from '../src/lib/session-branch-history.js';

// Fork-history ownership regression coverage.
//
// Requirement: two branches each recover valid ancestors (bound to their own
// content by message digest) and independent bodies, and content supplied
// after the branch closes does not leak into the recovered branch.
//
// Condition C1 (ancestor ownership): a session_history_origin must bind to the
// branch's own pending context message via messageDigest ===
// branchMessageDigest(pending).
// Condition C2 (body ownership): a branch's body is bounded by its
// descriptor.totalMessages; rows beyond that bound do not belong to it.
// Condition C3 (no post-branch leak): branch-content events after
// session_branch_complete must be rejected, not absorbed.
//
// The importer's session_branch_complete requires inputDigest to equal the
// SHA-256 of the accumulated history (node:crypto), so the test mirrors the
// source's digest computation from the exact event objects it feeds.

const HEX64 = 'abcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdef';

// session_branch descriptor (from-origin coverage, no system origins).
const descriptor = (totalMessages, contextMessageCount, branchId) => ({
  schema: BRANCH_HISTORY_SCHEMA,
  sourceGeneration: HEX64,
  totalMessages,
  contextMessageCount,
  coverage: { kind: 'from-origin', boundaryEvent: null, reason: null },
  branchId,
});

// A verified store body row (assistant text, single part, last row).
const bodyRow = (text, i) => ({
  type: BRANCH_HISTORY_MESSAGE,
  data: {
    role: 'assistant',
    text,
    part: 0,
    last: true,
    sourceEventId: `${i}${'b'.repeat(63)}`,
    sourceItemIndex: i,
  },
});

const contextMsg = (role, text) => ({
  type: role === 'system' ? 'system' : role === 'user' ? 'user_message' : 'assistant_message',
  data: { role, text, schemaVersion: 2 },
});

// origin event bound to the pending context message via its digest.
const origin = (ctxEvent, first, last) => ({
  type: BRANCH_HISTORY_ORIGIN,
  data: {
    messageDigest: branchMessageDigest(ctxEvent.data),
    origin: { first, last },
  },
});

// Mirror the source's SHA-256 accumulation:
//   "[" + startJSON + "," + branchJSON + (",",intermediateJSON)* + "]"
// using the exact event objects fed to accept().
function expectedInputDigest(startEvent, branchEvent, intermediateEvents) {
  const seed = `[${JSON.stringify({ type: startEvent.type, data: startEvent.data })},${JSON.stringify({
    type: branchEvent.type,
    data: branchEvent.data,
  })}`;
  const tail = intermediateEvents
    .map((e) => `,${JSON.stringify({ type: e.type, data: e.data })}`)
    .join('');
  return 'sha256:' + createHash('sha256').update(seed + tail + ']').digest('hex');
}

// Feed events; return collected accept() results and the first thrown error.
function feed(events) {
  const m = createBranchHistoryImport();
  const out = [];
  let error = null;
  for (const e of events) {
    try {
      out.push(m.accept(e));
    } catch (err) {
      error = err;
      break;
    }
  }
  return { out, error };
}

// Recovered body text = content of each {kind:'archive'} result, in order.
const bodyOf = (out) =>
  out.filter((r) => r.kind === 'archive').map((r) => r.message.content);
// Recovered ancestor context text = message.text of each {kind:'origin'} result.
const ancestorsOf = (out) =>
  out.filter((r) => r.kind === 'origin').map((r) => r.message.text);

describe('fork history ownership (verify-08)', () => {
  const startEvent = { type: 'session_start', data: { sessionId: 's1', language: 'en' } };

  // --- Positive C1/C2/C3: a branch recovers its body and a digest-bound ancestor ---
  it('recovers the branch body and a valid digest-bound ancestor, then completes', () => {
    const branchEvent = {
      type: 'session_branch',
      data: { ...descriptor(1, 1, 'b1'), sessionId: 's1' },
    };
    const row = bodyRow('body-one', 0);
    const ctx = contextMsg('user', 'q1');
    const originEvent = origin(ctx, 0, 0);
    const complete = {
      type: 'session_branch_complete',
      data: {
        schemaVersion: 2,
        messageCount: 1,
        inputDigest: expectedInputDigest(startEvent, branchEvent, [row, ctx, originEvent]),
      },
    };

    const { out, error } = feed([startEvent, branchEvent, row, ctx, originEvent, complete]);

    expect(error).toBeNull();
    expect(out.at(-1).kind).toBe('complete');
    expect(bodyOf(out)).toEqual(['body-one']);
    expect(ancestorsOf(out)).toEqual(['q1']);
  });

  // --- Positive independence: two branches recover distinct bodies and ancestors ---
  it('keeps two branches independent in body and ancestor content', () => {
    const branchA = {
      type: 'session_branch',
      data: { ...descriptor(1, 1, 'a'), sessionId: 's1' },
    };
    const rowA = bodyRow('alpha-body', 0);
    const ctxA = contextMsg('user', 'alpha-q');
    const originA = origin(ctxA, 0, 0);
    const completeA = {
      type: 'session_branch_complete',
      data: {
        schemaVersion: 2,
        messageCount: 1,
        inputDigest: expectedInputDigest(startEvent, branchA, [rowA, ctxA, originA]),
      },
    };

    const branchB = {
      type: 'session_branch',
      data: { ...descriptor(1, 1, 'b'), sessionId: 's1' },
    };
    const rowB = bodyRow('beta-body', 0);
    const ctxB = contextMsg('user', 'beta-q');
    const originB = origin(ctxB, 0, 0);
    const completeB = {
      type: 'session_branch_complete',
      data: {
        schemaVersion: 2,
        messageCount: 1,
        inputDigest: expectedInputDigest(startEvent, branchB, [rowB, ctxB, originB]),
      },
    };

    const outA = feed([startEvent, branchA, rowA, ctxA, originA, completeA]);
    const outB = feed([startEvent, branchB, rowB, ctxB, originB, completeB]);

    expect(outA.error).toBeNull();
    expect(outB.error).toBeNull();
    expect(outA.out.at(-1).kind).toBe('complete');
    expect(outB.out.at(-1).kind).toBe('complete');
    expect(bodyOf(outA.out)).toEqual(['alpha-body']);
    expect(bodyOf(outB.out)).toEqual(['beta-body']);
    expect(ancestorsOf(outA.out)).toEqual(['alpha-q']);
    expect(ancestorsOf(outB.out)).toEqual(['beta-q']);
  });

  // --- Negative C1: an origin whose messageDigest does not match the branch ---
  it('rejects an origin whose messageDigest does not match the pending context', () => {
    const branchEvent = {
      type: 'session_branch',
      data: { ...descriptor(1, 1, 'b1'), sessionId: 's1' },
    };
    const row = bodyRow('body-one', 0);
    const ctx = contextMsg('user', 'q1');
    // Only the messageDigest differs from the valid control above.
    const badOrigin = {
      type: BRANCH_HISTORY_ORIGIN,
      data: {
        messageDigest: `1${'0'.repeat(63)}`, // valid 64-hex, but wrong digest
        origin: { first: 0, last: 0 },
      },
    };
    const complete = {
      type: 'session_branch_complete',
      data: { schemaVersion: 2, messageCount: 1, inputDigest: 'irrelevant' },
    };

    const { out, error } = feed([startEvent, branchEvent, row, ctx, badOrigin, complete]);

    expect(error).toBeTruthy();
    expect(error.code).toBe('SESSION_BRANCH_HISTORY_INVALID');
    expect(out.at(-1).kind).not.toBe('complete');
  });

  // --- Negative C2: a body row beyond the branch totalMessages bound ---
  it('rejects a body row that exceeds the branch totalMessages bound', () => {
    const branchEvent = {
      type: 'session_branch',
      data: { ...descriptor(1, 0, 'b1'), sessionId: 's1' }, // totalMessages = 1
    };
    const complete = {
      type: 'session_branch_complete',
      data: { schemaVersion: 2, messageCount: 0, inputDigest: 'irrelevant' },
    };

    // Two rows supplied for a branch bound to one.
    const { out, error } = feed([
      startEvent,
      branchEvent,
      bodyRow('body-one', 0),
      bodyRow('stray-two', 1),
      complete,
    ]);

    expect(error).toBeTruthy();
    expect(error.code).toBe('SESSION_BRANCH_HISTORY_INVALID');
    expect(out.at(-1).kind).not.toBe('complete');
  });

  // --- Negative C3: a stray body message fed after complete is not absorbed ---
  it('does not absorb a body message fed after the branch completed', () => {
    const branchEvent = {
      type: 'session_branch',
      data: { ...descriptor(1, 1, 'b1'), sessionId: 's1' },
    };
    const row = bodyRow('body-one', 0);
    const ctx = contextMsg('user', 'q1');
    const originEvent = origin(ctx, 0, 0);
    const complete = {
      type: 'session_branch_complete',
      data: {
        schemaVersion: 2,
        messageCount: 1,
        inputDigest: expectedInputDigest(startEvent, branchEvent, [row, ctx, originEvent]),
      },
    };

    const { out, error } = feed([
      startEvent,
      branchEvent,
      row,
      ctx,
      originEvent,
      complete,
      bodyRow('stray-after-complete', 1), // arrives after complete
    ]);

    // The stray is rejected (not silently appended to the recovered branch).
    expect(error).toBeTruthy();
    expect(error.code).toBe('SESSION_BRANCH_HISTORY_INVALID');
    expect(bodyOf(out)).toEqual(['body-one']);
  });

  // --- Negative C3: a stray origin fed after complete is not absorbed ---
  it('does not absorb an origin event fed after the branch completed', () => {
    const branchEvent = {
      type: 'session_branch',
      data: { ...descriptor(1, 1, 'b1'), sessionId: 's1' },
    };
    const row = bodyRow('body-one', 0);
    const ctx = contextMsg('user', 'q1');
    const originEvent = origin(ctx, 0, 0);
    const complete = {
      type: 'session_branch_complete',
      data: {
        schemaVersion: 2,
        messageCount: 1,
        inputDigest: expectedInputDigest(startEvent, branchEvent, [row, ctx, originEvent]),
      },
    };
    const strayOrigin = { type: BRANCH_HISTORY_ORIGIN, data: { messageDigest: HEX64, origin: { first: 0, last: 0 } } };

    const { out, error } = feed([
      startEvent,
      branchEvent,
      row,
      ctx,
      originEvent,
      complete,
      strayOrigin, // arrives after complete
    ]);

    expect(error).toBeTruthy();
    expect(error.code).toBe('SESSION_BRANCH_HISTORY_INVALID');
    expect(bodyOf(out)).toEqual(['body-one']);
  });
});

import { describe, it, expect } from 'vitest';
import { createHash } from 'node:crypto';
import {
  createBranchHistoryImport,
  branchMessageDigest,
  BRANCH_HISTORY_SCHEMA,
  BRANCH_HISTORY_MESSAGE,
  BRANCH_HISTORY_ORIGIN,
} from '../src/lib/session-branch-history.js';

// Fork-history ownership regression coverage (verify-08).
//
// Requirement: each branch recovers valid ancestors (an origin bound to the
// branch's own recovered context by message digest, within its own rows) and
// an independent body, and content supplied after the branch completes does not
// leak into the completed archive.
//
// Condition C1 (ancestor ownership): an origin's messageDigest must equal
// branchMessageDigest of the branch's own pending context message.
// Condition C2 (body ownership): a branch body row is only accepted while
// state.rows < descriptor.totalMessages; rows beyond the bound are rejected.
// Condition C3 (no post-branch leak): BRANCH_HISTORY_* fed after
// session_branch_complete is rejected (the importer throws), never absorbed.

// Deterministic 64-lowercase-hex value (matches the source's hash predicate).
const hex64 = (seed) => createHash('sha256').update('seed:' + seed).digest('hex');

const start = { type: 'session_start', data: { sessionId: 's1' } };

// Replicate the source's exact SHA-256 accumulation for the complete inputDigest:
// `[start,branch` then `,event` per intermediate event then `]`.
function computeInputDigest(branchEvent, midEvents) {
  const d = createHash('sha256').update(
    `[${JSON.stringify(start)},${JSON.stringify({ type: branchEvent.type, data: branchEvent.data })}`,
  );
  for (const ev of midEvents) d.update(`,${JSON.stringify({ type: ev.type, data: ev.data })}`);
  d.update(']');
  return `sha256:${d.digest('hex')}`;
}

const makeRow = (text, i) => ({
  type: BRANCH_HISTORY_MESSAGE,
  data: {
    role: 'assistant',
    text,
    part: 0,
    last: true,
    sourceEventId: hex64('ev' + i + text),
    sourceItemIndex: i,
  },
});

const makeCtx = (i, text) => ({ type: 'user_message', data: { role: 'user', text: text ?? 'q' + i } });

// Origin whose messageDigest is bound to the given context data object.
const makeOrigin = (ctxData, first, last) => ({
  type: BRANCH_HISTORY_ORIGIN,
  data: { messageDigest: branchMessageDigest(ctxData), origin: { first, last } },
});

function buildImport(events) {
  const m = createBranchHistoryImport();
  const archives = [];
  let completed = false;
  for (const ev of events) {
    const res = m.accept(ev);
    if (res && res.kind === 'archive') archives.push(res.message.content);
    if (res && res.kind === 'complete') {
      completed = true;
      break;
    }
  }
  return { m, archives, completed };
}

describe('fork history ownership (verify-08)', () => {
  const branchFor = (totalMessages, contextMessageCount, sourceGeneration) => ({
    type: 'session_branch',
    data: {
      history: {
        schema: BRANCH_HISTORY_SCHEMA,
        sourceGeneration,
        totalMessages,
        contextMessageCount,
        coverage: { kind: 'from-origin', boundaryEvent: null, reason: null },
      },
    },
  });

  // --- Positive: one branch recovers its two body rows and two bound ancestors ---
  it('recovers a branch body and digest-bound ancestors and completes', () => {
    const branch = branchFor(2, 2, hex64('gen1'));
    const ctxA = makeCtx(0, 'q1');
    const ctxB = makeCtx(1, 'q2');
    const mid = [
      makeRow('body-one', 0),
      makeRow('body-two', 1),
      ctxA,
      ctxB,
      makeOrigin(ctxA.data, 0, 0),
      makeOrigin(ctxB.data, 1, 1),
    ];
    const events = [
      start,
      branch,
      ...mid,
      {
        type: 'session_branch_complete',
        data: { schemaVersion: 2, messageCount: 2, inputDigest: computeInputDigest(branch, mid) },
      },
    ];
    const { archives, completed } = buildImport(events);
    expect(completed).toBe(true);
    expect(archives).toEqual(['body-one', 'body-two']);
  });

  // --- Positive: two independent forks each recover own body + own ancestor ---
  it('keeps two forks independent in body and ancestor binding', () => {
    const runBranch = (tag, q) => {
      const branch = branchFor(1, 1, hex64('gen' + tag));
      const ctx = makeCtx(0, q);
      const mid = [makeRow(tag + '-body', 0), ctx, makeOrigin(ctx.data, 0, 0)];
      const events = [
        start,
        branch,
        ...mid,
        {
          type: 'session_branch_complete',
          data: { schemaVersion: 2, messageCount: 1, inputDigest: computeInputDigest(branch, mid) },
        },
      ];
      const r = buildImport(events);
      return { ...r, originDigest: makeOrigin(ctx.data, 0, 0).data.messageDigest };
    };
    const a = runBranch('alpha', 'alpha-q');
    const b = runBranch('beta', 'beta-q');
    expect(a.completed).toBe(true);
    expect(b.completed).toBe(true);
    expect(a.archives).toEqual(['alpha-body']);
    expect(b.archives).toEqual(['beta-body']);
    // Ancestors are bound to their own fork's context, not the other's.
    expect(a.originDigest).not.toBe(b.originDigest);
  });

  // --- Negative C1: origin digest does not match the branch's own context ---
  it('rejects an origin whose messageDigest does not bind to the branch context', () => {
    const branch = branchFor(1, 1, hex64('genC1'));
    const ctx = makeCtx(0, 'q1');
    const events = [
      start,
      branch,
      makeRow('body', 0),
      ctx,
      { type: BRANCH_HISTORY_ORIGIN, data: { messageDigest: hex64('wrong'), origin: { first: 0, last: 0 } } },
    ];
    expect(() => buildImport(events)).toThrow();
  });

  // --- Negative C2: a body row beyond the branch totalMessages bound ---
  it('rejects a branch body row that exceeds totalMessages', () => {
    const branch = branchFor(1, 0, hex64('genC2'));
    const events = [start, branch, makeRow('one', 0), makeRow('two', 1)];
    expect(() => buildImport(events)).toThrow();
  });

  // --- Negative C3a: stray body message after complete is rejected ---
  it('rejects a branch body message fed after completion (no post-branch leak)', () => {
    const branch = branchFor(1, 1, hex64('genC3a'));
    const ctx = makeCtx(0, 'q1');
    const mid = [makeRow('body', 0), ctx, makeOrigin(ctx.data, 0, 0)];
    const valid = [
      start,
      branch,
      ...mid,
      {
        type: 'session_branch_complete',
        data: { schemaVersion: 2, messageCount: 1, inputDigest: computeInputDigest(branch, mid) },
      },
    ];
    const { m, completed, archives } = buildImport(valid);
    expect(completed).toBe(true);
    expect(archives).toEqual(['body']);
    expect(() => m.accept(makeRow('stray', 1))).toThrow();
  });

  // --- Negative C3b: stray origin after complete is rejected ---
  it('rejects a stray origin fed after completion (no post-branch leak)', () => {
    const branch = branchFor(1, 1, hex64('genC3b'));
    const ctx = makeCtx(0, 'q1');
    const mid = [makeRow('body', 0), ctx, makeOrigin(ctx.data, 0, 0)];
    const valid = [
      start,
      branch,
      ...mid,
      {
        type: 'session_branch_complete',
        data: { schemaVersion: 2, messageCount: 1, inputDigest: computeInputDigest(branch, mid) },
      },
    ];
    const { m, completed } = buildImport(valid);
    expect(completed).toBe(true);
    expect(() => m.accept(makeOrigin(ctx.data, 1, 1))).toThrow();
  });
});

