    const valid = store.readVerifiedEvents(id).at(-1).data;
    store.appendCompactEvent(id, {
      ...valid,
      messages: [{ role: "user", content: "replacement" }],
    });
    expect(texts(readSessionTranscriptHistory(id))).toEqual(["replacement"]);
    store.appendCompactEvent(id, {
      ...valid,
      canonical: { ...valid.canonical, digest: "invalid" },
    });
    expect(readSessionTranscriptHistory(id).coverage.reason).toBe(
      "context-snapshot",
    );
  });

  it("reads through the command without modifying authority and rejects a forged tail", async () => {
    const id = "history-command";
    start(id, 2);
    const before = store.readVerifiedEvents(id);
    const program = new Command();
    registerSessionShowSubcommand(program.command("session"), program);
    const output = vi.spyOn(console, "log").mockImplementation(() => {});
    try {
      await program.parseAsync(
        [
          "session",
          "show",
          "--json",
          "--history",
          "--page-size",
          "2",
          "--",
          id,
        ],
        { from: "user" },
      );
      const page = parseTranscriptPage(output.mock.calls.at(-1)[0], id);
      expect(page.messages).toHaveLength(2);
      expect(store.readVerifiedEvents(id)).toEqual(before);
    } finally {
      output.mockRestore();
    }
    appendFileSync(
      join(root, "home", "sessions", `${id}.jsonl`),
      '{"type":"assistant_message","data":{"role":"assistant","content":"forged"}}\n',
    );
    expect(() => readSessionTranscriptHistory(id)).toThrow();
  });

  it("bounds retained bytes and traverses oversized rows without dropping page identities", () => {
    const events = Array.from({ length: 12 }, (_, i) => ({
      type: "assistant_message",
      hash: (i + 1).toString(16).padStart(64, "0"),
      data: { role: "assistant", content: "中".repeat(210000) },
    }));
    let cursor = null;
    const rows = [];
    do {
      const projection = createSessionTranscriptHistoryProjection("large", {
        limit: 100,
        cursor,
      });
      events.forEach((event) => projection.accept(event));
      const page = projection.finish({
        headHash: events.at(-1).hash,
        eventCount: events.length,
      });
      expect(Buffer.byteLength(JSON.stringify(page))).toBeLessThan(
        1024 * 1024 + 4096,
      );
      expect(
        page.messages.every((m) => m.truncated && m.text.length === 200000),
      ).toBe(true);
      rows.unshift(...page.messages);
      cursor = page.nextCursor;
    } while (cursor);
    expect(rows.map((row) => row.ordinal)).toEqual(
      events.map((_, index) => index),
    );
    expect(new Set(rows.map((row) => row.id)).size).toBe(events.length);
  });
});

import { canonicalDigest } from "@chainlesschain/context-memory-kernel";
import { createHash } from "node:crypto";
import { SESSION_GENERATION_AUTHORITY_FIELD } from "../harness/session-list-index.js";
import {
  encodePersistedMessage,
  decodeVerifiedPersistedMessage,
  getDurableSystemMessageProvenance,
  projectCanonicalResumeMessages,
} from "./session-message-provenance.js";

export const BRANCH_HISTORY_SCHEMA = "chainlesschain.session-branch-history/v1";
export const BRANCH_HISTORY_SYSTEM_ORIGINS_SCHEMA =
  "chainlesschain.session-branch-history/v2";
export const BRANCH_HISTORY_MESSAGE = "session_history_message";
export const BRANCH_HISTORY_ORIGIN = "session_history_origin";
const capabilities = new WeakMap();

export const branchContextDigest = (messages) =>
  canonicalDigest(
    projectCanonicalResumeMessages(messages, { strict: true }).map(
      encodePersistedMessage,
    ),
    "chainlesschain.branch-history-context/v1",
  );
export const branchMessageDigest = (message) =>
  canonicalDigest(message, "chainlesschain.branch-history-message/v1");

// A caller cannot smuggle JSON-shaped history into a new authority chain. The
// capability exists only inside a verified source projection's synchronous lock.
export function withSessionBranchHistory(plan, task) {
  if (typeof task !== "function" || task.constructor?.name === "AsyncFunction")
    throw new TypeError("Branch history consumer must be synchronous");
  const capability = Object.freeze({});
  capabilities.set(capability, plan);
  try {
    const result = task(capability);
    if (result && typeof result.then === "function")
      throw new TypeError("Branch history consumer must be synchronous");
    return result;
  } finally {
    capabilities.delete(capability);
  }
}

export function resolveSessionBranchHistory(
  capability,
  parentSessionId,
  messages,
) {
  if (capability == null) return null;
  const plan = capabilities.get(capability);
  if (
    !plan ||
    plan.parentSessionId !== parentSessionId ||
    plan.contextDigest !== branchContextDigest(messages)
  ) {
    throw new Error(
      "Branch history capability is expired or does not match the branch",
    );
  }
  return plan;
}

export function createBranchHistoryImport() {
  let start = null;
  let index = 0;
  let active = null;
  const hash = (value) =>
    typeof value === "string" && /^[a-f0-9]{64}$/u.test(value);
  const integer = (value) => Number.isSafeInteger(value) && value >= 0;
  const invalid = () => {
    const error = new Error(
      "Branch display history is incomplete or inconsistent",
    );
    error.code = "SESSION_BRANCH_HISTORY_INVALID";
    throw error;
  };
  const require = (condition) => {
    if (!condition) invalid();
  };
  return {
    accept(event) {
      index += 1;
      if (index === 1 && event.type === "session_start") {
        const data = { ...event.data };
        delete data[SESSION_GENERATION_AUTHORITY_FIELD];
        start = { type: event.type, data };
      }
      if (event.type === "session_branch" && event.data?.history != null) {
        const descriptor = event.data.history;
        require(
          index === 2 &&
            start &&
            !active &&
            [
              BRANCH_HISTORY_SCHEMA,
              BRANCH_HISTORY_SYSTEM_ORIGINS_SCHEMA,
            ].includes(descriptor.schema) &&
            hash(descriptor.sourceGeneration) &&
            integer(descriptor.totalMessages) &&
            integer(descriptor.contextMessageCount) &&
            descriptor.contextMessageCount <= 32768,
        );
        const coverage = descriptor.coverage;
        require(
          coverage?.kind === "from-origin"
            ? coverage.boundaryEvent === null && coverage.reason === null
            : coverage?.kind === "snapshot-boundary" &&
                hash(coverage.boundaryEvent) &&
                [
                  "timeline-replacement",
                  "context-snapshot",
                  "branch-snapshot",
                ].includes(coverage.reason),
        );
        const digest = createHash("sha256").update(
          `[${JSON.stringify(start)},${JSON.stringify({ type: event.type, data: event.data })}`,
        );
        active = {
          descriptor,
          digest,
          rows: 0,
          contexts: 0,
          pending: null,
          textParts: [],
          textBytes: 0,
          textIdentity: null,
          contextStarted: false,
        };
        return { kind: "start", coverage };
      }
      if (!active) {
        if (
          [BRANCH_HISTORY_MESSAGE, BRANCH_HISTORY_ORIGIN].includes(
            event.type,
          ) ||
          (event.type === "session_branch_complete" &&
            event.data?.schemaVersion === 2)
        )
          invalid();
        return null;
      }
      const state = active;
      if (event.type === "session_branch_complete") {
        require(
          !state.pending &&
            state.textParts.length === 0 &&
            state.rows === state.descriptor.totalMessages &&
            state.contexts === state.descriptor.contextMessageCount &&
            event.data?.schemaVersion === 2 &&
            event.data.messageCount === state.contexts &&
            event.data.inputDigest ===
              `sha256:${state.digest.update("]").digest("hex")}`,
        );
        active = null;
        return { kind: "complete" };
      }
      state.digest.update(
        `,${JSON.stringify({ type: event.type, data: event.data })}`,
      );
      if (event.type === BRANCH_HISTORY_MESSAGE) {
        const row = event.data;
        require(
          !state.contextStarted &&
            state.rows < state.descriptor.totalMessages &&
            ["user", "assistant", "tool"].includes(row?.role) &&
            typeof row.text === "string" &&
            row.text.length <= 128 * 1024 &&
            row.part === state.textParts.length &&
            typeof row.last === "boolean" &&
            hash(row.sourceEventId) &&
            integer(row.sourceItemIndex),
        );
        const identity = `${row.role}:${row.sourceEventId}:${row.sourceItemIndex}`;
        require(state.textIdentity === null || state.textIdentity === identity);
        state.textIdentity = identity;
        state.textBytes += Buffer.byteLength(row.text);
        require(
          state.textBytes <= 16 * 1024 * 1024 && state.textParts.length < 256,
        );
        state.textParts.push(row.text);
        if (!row.last) return { kind: "archive-part" };
        const message = { role: row.role, content: state.textParts.join("") };
        state.textParts = [];
        state.textBytes = 0;
        state.textIdentity = null;
        state.rows += 1;
        return { kind: "archive", message };
      }
      if (
        ["user_message", "assistant_message", "system"].includes(event.type)
      ) {
        require(
          !state.pending &&
            state.textParts.length === 0 &&
            state.rows === state.descriptor.totalMessages &&
            state.contexts < state.descriptor.contextMessageCount &&
            event.data?.role ===
              {
                user_message: "user",
                assistant_message: "assistant",
                system: "system",
              }[event.type],
        );
        state.contextStarted = true;
        state.pending = event.data;
        return { kind: "context" };
      }
      if (event.type === BRANCH_HISTORY_ORIGIN) {
        const message = state.pending;
        const origin = event.data?.origin;
        require(
          message && event.data.messageDigest === branchMessageDigest(message),
        );
        require(
          origin === null
            ? message.role === "system"
            : origin &&
                integer(origin.first) &&
                integer(origin.last) &&
                origin.first <= origin.last &&
                origin.last < state.rows &&
                (message.role !== "system" ||
                  (state.descriptor.schema ===
                    BRANCH_HISTORY_SYSTEM_ORIGINS_SCHEMA &&
                    getDurableSystemMessageProvenance(
                      decodeVerifiedPersistedMessage(message),
                    ))),
        );
        state.contexts += 1;
        state.pending = null;
        return { kind: "origin", message, origin };
      }
      invalid();
    },
    finish() {
      if (active) invalid();
    },
  };
}

/**
 * Session branch planning (P0-3 "从这里分支" — the fourth restore action from
 * CLAUDE_CODE_IDE_INCREMENTAL_GAP_ANALYSIS_2026-07-13.md). Pure module: no RNG,
 * clock, fs or git — deterministic plans + lineage integrity checks.
 */
import { describe, it, expect } from "vitest";
import { TURN_COVERAGE, TurnBindingLog } from "../../src/lib/turn-binding.js";
import {
  deriveBranchId,
  deriveBranchSessionId,
  planSessionBranch,
  validateBranchLineage,
} from "../../src/lib/session-branch.js";

/** A FULL-coverage turn: mutated files WITH a checkpoint, no side-effects. */
function fullTurn() {
  const log = new TurnBindingLog();
  log.startTurn("turn-3", { conversationOffset: 3 });
  log.recordToolCall("turn-3", "tc-1", { name: "write_file" });
  log.bindCheckpoint("turn-3", "cp-abc");
  return log.get("turn-3");
}

describe("deriveBranchId", () => {
  it("is deterministic — same inputs hash to the same id", () => {
    expect(deriveBranchId("s1", "turn-3", 0)).toBe(
      deriveBranchId("s1", "turn-3", 0),
    );
  });
  it("disambiguates two branches off the SAME turn via seq", () => {
    expect(deriveBranchId("s1", "turn-3", 0)).not.toBe(
      deriveBranchId("s1", "turn-3", 1),
    );
  });
  it("differs by parent session and by turn", () => {
    expect(deriveBranchId("s1", "turn-3", 0)).not.toBe(
      deriveBranchId("s2", "turn-3", 0),
    );
    expect(deriveBranchId("s1", "turn-3", 0)).not.toBe(
      deriveBranchId("s1", "turn-4", 0),
    );
  });
});

describe("deriveBranchSessionId", () => {
  it("derives a traversal-safe id (no path separators survive)", () => {
    const id = deriveBranchSessionId("../evil/id", "ab/cd");
    expect(id).not.toContain("/");
    expect(id).not.toContain("\\");
    expect(id).toMatch(/^[A-Za-z0-9._~-]+$/);
  });
  it("embeds the parent and branch id", () => {
    expect(deriveBranchSessionId("s1", "deadbeef")).toBe("s1-b-deadbeef");
  });
});

describe("planSessionBranch", () => {
  it("targets a NEW session, preserves the parent, never inherits grants", () => {
    const plan = planSessionBranch({
      parentSessionId: "s1",
      turn: fullTurn(),
    });
    expect(plan.branchSessionId).not.toBe("s1");
    expect(plan.branchSessionId).toContain("s1-b-");
    expect(plan.preservesParent).toBe(true);
    expect(plan.inheritSessionGrants).toBe(false);
    expect(plan.parentTurnId).toBe("turn-3");
    expect(plan.parentSessionId).toBe("s1");
  });

  it("keeps history up to the branch-point turn (truncate offset)", () => {
    const plan = planSessionBranch({ parentSessionId: "s1", turn: fullTurn() });
    expect(plan.conversationTruncateTo).toBe(3);
    expect(plan.fileCheckpointId).toBe("cp-abc");
    expect(plan.coverage).toBe(TURN_COVERAGE.FULL);
  });

  it("emits no warnings for a clean, read-only FULL branch point", () => {
    // FULL coverage AND no file mutation → nothing irreversible, no collision.
    const log = new TurnBindingLog();
    log.startTurn("turn-0", { conversationOffset: 0 });
    log.recordToolCall("turn-0", "r", { name: "read_file" });
    const plan = planSessionBranch({
      parentSessionId: "s1",
      turn: log.get("turn-0"),
    });
    expect(plan.coverage).toBe(TURN_COVERAGE.FULL);
    expect(plan.requiresWorktree).toBe(false);
    expect(plan.warnings).toEqual([]);
  });

  it("requires a worktree when the branch intends to write", () => {
    const readOnlyLog = new TurnBindingLog();
    readOnlyLog.startTurn("turn-1", { conversationOffset: 1 });
    readOnlyLog.recordToolCall("turn-1", "tc", { name: "read_file" });
    const turn = readOnlyLog.get("turn-1");
    expect(turn.coverage).toBe(TURN_COVERAGE.FULL);

    const readPlan = planSessionBranch({ parentSessionId: "s1", turn });
    expect(readPlan.requiresWorktree).toBe(false);

    const writePlan = planSessionBranch({
      parentSessionId: "s1",
      turn,
      writeIntent: true,
    });
    expect(writePlan.requiresWorktree).toBe(true);
    expect(writePlan.warnings.join(" ")).toContain("isolated worktree");
  });

  it("requires a worktree when the branch point already mutated files", () => {
    // FULL turn that mutated files (has a checkpoint) → a divergent branch that
    // also writes would collide, so default to an isolated worktree.
    const plan = planSessionBranch({ parentSessionId: "s1", turn: fullTurn() });
    expect(plan.requiresWorktree).toBe(true);
  });

  it("warns honestly on PARTIAL coverage (irreversible side-effects)", () => {
    const log = new TurnBindingLog();
    log.startTurn("turn-2", { conversationOffset: 2 });
    log.recordToolCall("turn-2", "sh", { name: "run_shell" });
    log.bindCheckpoint("turn-2", "cp-x");
    const plan = planSessionBranch({
      parentSessionId: "s1",
      turn: log.get("turn-2"),
    });
    expect(plan.coverage).toBe(TURN_COVERAGE.PARTIAL);
    expect(plan.warnings.join(" ")).toContain("irreversible side-effects");
  });

  it("warns when there is no file checkpoint (NONE coverage)", () => {
    const log = new TurnBindingLog();
    log.startTurn("turn-5", { conversationOffset: 5 });
    log.recordToolCall("turn-5", "ed", { name: "edit_file" }); // mutated, no checkpoint
    const turn = log.get("turn-5");
    expect(turn.coverage).toBe(TURN_COVERAGE.NONE);
    const plan = planSessionBranch({ parentSessionId: "s1", turn });
    expect(plan.warnings.join(" ")).toContain("no file checkpoint");
    expect(plan.requiresWorktree).toBe(true); // NONE = mutated files at point
  });

  it("warns and still preserves the parent on a missing conversation offset", () => {
    const log = new TurnBindingLog();
    log.startTurn("turn-9"); // no offset
    const plan = planSessionBranch({
      parentSessionId: "s1",
      turn: log.get("turn-9"),
    });
    expect(plan.conversationTruncateTo).toBeNull();
    expect(plan.warnings.join(" ")).toContain("full parent history");
    expect(plan.preservesParent).toBe(true);
  });

  it("handles an unknown/absent turn without throwing", () => {
    const plan = planSessionBranch({ parentSessionId: "s1", turn: null });
    expect(plan.branchId).toBeNull();
    expect(plan.preservesParent).toBe(true);
    expect(plan.inheritSessionGrants).toBe(false);
    expect(plan.warnings.join(" ")).toContain("nothing to branch from");
  });

  it("honors an explicit branch session id", () => {
    const plan = planSessionBranch({
      parentSessionId: "s1",
      turn: fullTurn(),
      branchSessionId: "my-branch",
    });
    expect(plan.branchSessionId).toBe("my-branch");
  });
});

describe("validateBranchLineage", () => {
  it("accepts a clean tree (root + children)", () => {
    const res = validateBranchLineage([
      { sessionId: "root", parentSessionId: null },
      { sessionId: "b1", parentSessionId: "root" },
      { sessionId: "b2", parentSessionId: "b1" },
    ]);
    expect(res.ok).toBe(true);
    expect(res.cycles).toEqual([]);
    expect(res.orphans).toEqual([]);
  });

  it("flags an orphan (parent not present)", () => {
    const res = validateBranchLineage([
      { sessionId: "b1", parentSessionId: "ghost" },
    ]);
    expect(res.ok).toBe(false);
    expect(res.orphans).toContain("b1");
  });

  it("detects a cycle — a branch cannot be its own ancestor", () => {
    const res = validateBranchLineage([
      { sessionId: "a", parentSessionId: "b" },
      { sessionId: "b", parentSessionId: "a" },
    ]);
    expect(res.ok).toBe(false);
    expect(res.cycles.length).toBe(1);
    expect(res.cycles[0].sort()).toEqual(["a", "b"]);
  });

  it("ignores malformed records", () => {
    const res = validateBranchLineage([null, { parentSessionId: "x" }, 42]);
    expect(res.ok).toBe(true);
  });
});

import { canonicalDigest } from "@chainlesschain/context-memory-kernel";
import {
  readVerifiedProjection,
  projectWsTurnMessages,
} from "../harness/jsonl-session-store.js";
import { contextItemsToMessages } from "./context-memory-kernel/message-adapter.js";
import {
  displayTranscriptText,
  transcriptTextParts,
  boundTranscriptRow,
} from "./session-transcript-page.js";
import { createSessionHistoryOrigins } from "./session-history-origins.js";
import { getDurableSystemMessageProvenance } from "./session-message-provenance.js";
import {
  BRANCH_HISTORY_SCHEMA,
  BRANCH_HISTORY_SYSTEM_ORIGINS_SCHEMA,
  BRANCH_HISTORY_MESSAGE,
  branchContextDigest,
  withSessionBranchHistory,
  createBranchHistoryImport,
} from "./session-branch-history.js";

const HASH = /^[a-f0-9]{64}$/u;
const SCHEMA = "chainlesschain.session-transcript-page/v2";
const CHANGES_SCHEMA = "chainlesschain.session-transcript-changes/v1";
const MAX_PAGE_BYTES = 1024 * 1024;
const MAX_HISTORY_RANGES = 16384;

// Enumerate all possible display sources, including replacement snapshots.
// Their physical sequence never changes when the selected history rewinds.
function eventMessages(event, imported = null) {
  if (event.type === BRANCH_HISTORY_MESSAGE)
    return imported?.kind === "archive" ? [imported.message] : [];
  if (
    ["compact", "checkpoint_timeline_commit"].includes(event.type) &&
    Array.isArray(event.data?.messages)
  )
    return event.data.messages;
  if (["user_message", "assistant_message", "system"].includes(event.type))
    return [event.data];
  if (event.type === "ws_turn") {
    const pair = projectWsTurnMessages(event);
    if (pair) return [pair.user, pair.assistant];
  }
  return [];
}
const displayable = (message) =>
  ["user", "assistant", "tool"].includes(message?.role);

// compact also historically meant import, rewind or a session-end snapshot.
// Only a verified Kernel compaction payload proves this is a context update.
// A copied fork retains the source payload, so do not compare its sessionId to
// the destination namespace (the store independently verifies fork authority).
function isContextCompaction(data) {
  const canonical = data?.canonical;
  if (
    canonical?.schema !== "chainlesschain.context-compaction/v1" ||
    canonical.schemaVersion !== 1 ||
    !["committed", "degraded"].includes(canonical.status) ||
    !Array.isArray(canonical.outputItems)
  )
    return false;
  try {
    const { digest, ...body } = canonical;
    if (canonicalDigest(body, "chainlesschain.compaction-event/v1") !== digest)
      return false;
    const content = (messages) =>
      messages
        .filter((message) => message?.role !== "system")
        .map(({ role, content, tool_calls, tool_call_id }) => ({
          role,
          content,
          tool_calls,
          tool_call_id,
        }));
    return (
      canonicalDigest(
        content(contextItemsToMessages(canonical.outputItems)),
      ) === canonicalDigest(content(data.messages))
    );
  } catch {
    return false;
  }
}

function staleCursor() {
  const error = new Error("Transcript history changed; reload the latest page");
  error.code = "SESSION_TRANSCRIPT_CURSOR_STALE";
  return error;
}

export function createSessionTranscriptHistoryProjection(
  sessionId,
  { limit = 50, cursor = null, after = null } = {},
  branch = null,
) {
  if (!Number.isSafeInteger(limit) || limit < 1 || limit > 100)
    throw new TypeError("transcript page limit must be 1–100");
  if (cursor !== null && after !== null)
    throw new TypeError(
      "History before and after cursors are mutually exclusive",
    );
  const incremental = after !== null;
  const encodedCursor = incremental ? after : cursor;
  let anchor = null;
  if (encodedCursor !== null) {
    if (
      typeof encodedCursor !== "string" ||
      !/^[\w-]{1,1024}$/u.test(encodedCursor)
    )
      throw new TypeError("invalid transcript history cursor");
    try {
      anchor = JSON.parse(
        Buffer.from(encodedCursor, "base64url").toString("utf8"),
      );
    } catch {
      throw new TypeError("invalid transcript history cursor");
    }
    if (
      !anchor ||
      anchor.sessionId !== sessionId ||
      !HASH.test(anchor.generation) ||
      !HASH.test(anchor.revision) ||
      !Number.isSafeInteger(anchor.eventCount) ||
      anchor.eventCount < 1 ||
      (incremental
        ? anchor.v !== 1 ||
          anchor.view !== "history-sync" ||
          !Number.isSafeInteger(anchor.offset) ||
          anchor.offset < 0
        : anchor.v !== 2 ||
          !Number.isSafeInteger(anchor.before) ||
          anchor.before < 1)
    )
      throw new TypeError("invalid transcript history cursor");
  }
  let generation = null;
  let eventCount = 0;
  let count = 0;
  let bytes = 0;
  let rows = [];
  let incrementalFull = false;
  let anchored = !anchor;
  let coverage = { kind: "from-origin", boundaryEvent: null, reason: null };
  const origins = createSessionHistoryOrigins();
  const branchImport = createBranchHistoryImport();
  let physical = 0;
  let ranges = [];
  let needsReplay = false;

  function displayRow(message, event, index, ordinal) {
    return boundTranscriptRow({
      id: `${sessionId}:${event.hash}:${index}`,
      eventId: event.hash,
      itemIndex: index,
      ordinal,
      role: message.role,
      ...displayTranscriptText(message.content),
    });
  }
  function collect(message, event, index, ordinal) {
    if (incremental) {
      if (ordinal < anchor.offset || incrementalFull) return;
    } else if (anchor && ordinal >= anchor.before) return;
    const row = displayRow(message, event, index, ordinal);
    const rowBytes = Buffer.byteLength(JSON.stringify(row));
    if (
      incremental &&
      (rows.length >= limit || bytes + rowBytes > MAX_PAGE_BYTES)
    ) {
      // Keep the FIRST contiguous prefix after the cursor. Skipping an oversized
      // next row and admitting later small rows would permanently omit messages.
      incrementalFull = true;
      return;
    }
    rows.push(row);
    bytes += rowBytes;
    while (rows.length > limit || bytes > MAX_PAGE_BYTES)
      bytes -= Buffer.byteLength(JSON.stringify(rows.shift()));
  }
  function append(message, event, index) {
    if (!displayable(message)) return;
    if (ranges.at(-1)?.end === physical) ranges.at(-1).end += 1;
    else {
      if (ranges.length >= MAX_HISTORY_RANGES) {
        const error = new Error(
          "Transcript history has too many disjoint ranges",
        );
        error.code = "SESSION_TRANSCRIPT_HISTORY_LIMIT";
        throw error;
      }
      ranges.push({ start: physical, end: physical + 1 });
    }
    physical += 1;
    collect(message, event, index, count++);
  }
  function rewind(cutoff) {
    let remaining = cutoff;
    ranges = ranges.filter((range) => {
      if (remaining === 0) return false;
      const kept = Math.min(remaining, range.end - range.start);
      range.end = range.start + kept;
      remaining -= kept;
      return true;
    });
    count = cutoff;
    rows = [];
    bytes = 0;
    incrementalFull = false;
    needsReplay = true;
  }
  function boundary(event, reason) {
    coverage = { kind: "snapshot-boundary", boundaryEvent: event.hash, reason };
  }
  function visitSelected(authority, visit) {
    let source = 0;
    let rangeIndex = 0;
    let ordinal = 0;
    const replayImport = createBranchHistoryImport();
    authority.replayEvents((event) => {
      const imported = replayImport.accept(event);
      eventMessages(event, imported).forEach((message, index) => {
        if (!displayable(message)) return;
        while (ranges[rangeIndex] && source >= ranges[rangeIndex].end)
          rangeIndex += 1;
        const range = ranges[rangeIndex];
        if (range && source >= range.start)
          visit(message, event, index, ordinal++);
        source += 1;
      });
    });
    replayImport.finish();
    if (ordinal !== count || source !== physical)
      throw new Error("Transcript history replay did not match its selection");
  }
  return {
    accept(event) {
      if (!HASH.test(event.hash))
        throw new TypeError("verified event hash required");
      eventCount += 1;
      generation ||= event.hash;
      const imported = branchImport.accept(event);
      const messages = eventMessages(event, imported);
      if (imported?.kind === "start") {
        coverage = { ...imported.coverage };
      } else if (imported?.kind === "archive") {
        append(messages[0], event, 0);
      } else if (imported?.kind === "archive-part") {
        // A logical row may span several bounded persistence records.
      } else if (imported?.kind === "context") {
        physical += messages.filter(displayable).length;
      } else if (imported?.kind === "origin") {
        origins.appendMappedPersisted(imported.message, imported.origin);
      } else if (imported?.kind === "complete") {
        // The complete import is independently anchored in this session.
      } else if (
        ["compact", "checkpoint_timeline_commit"].includes(event.type) &&
        Array.isArray(event.data?.messages)
      ) {
        const cutoff =
          event.type === "checkpoint_timeline_commit"
            ? origins.rewind(event, count)
            : null;
        if (cutoff !== null) {
          rewind(cutoff);
          generation = event.hash;
          physical += messages.filter(displayable).length;
        } else if (
          event.type === "checkpoint_timeline_commit" &&
          origins.summarize(event)
        ) {
          // The verified rewrite changes model context only. Original rows,
          // coverage and old display cursors continue to describe the archive.
          physical += messages.filter(displayable).length;
        } else if (
          event.type === "compact" &&
          count > 0 &&
          isContextCompaction(event.data)
        ) {
          origins.compact(event.data);
          physical += messages.filter(displayable).length;
        } else {
          // Legacy or unverifiable lineage can authorize only its snapshot.
          generation = event.hash;
          count = 0;
          bytes = 0;
          rows = [];
          incrementalFull = false;
          ranges = [];
          needsReplay = false;
          origins.snapshot(messages);
          boundary(
            event,
            event.type === "checkpoint_timeline_commit"
              ? "timeline-replacement"
              : "context-snapshot",
          );
          messages.forEach((message, index) => append(message, event, index));
        }
      } else if (event.type === "session_branch") {
        boundary(event, "branch-snapshot");
      } else {
        messages.forEach((message, index) => {
          origins.appendPersisted(message, count);
          append(message, event, index);
        });
      }
      if (anchor && eventCount === anchor.eventCount) {
        anchored =
          event.hash === anchor.revision &&
          (incremental ? anchor.offset : anchor.before) <= count &&
          generation === anchor.generation;
      }
    },
    finish(authority) {
      branchImport.finish();
      if (branch) {
        const prefix = origins.branchPrefix(
          branch.messages,
          authority.headHash,
          count,
        );
        if (!prefix) return branch.consume(null);
        rewind(prefix.cutoff);
        const contextEntries = prefix.entries.filter(
          ({ message }) =>
            ["user", "assistant"].includes(message.role) ||
            (message.role === "system" &&
              getDurableSystemMessageProvenance(message)),
        );
        const contextOrigins = contextEntries.map(({ origin }) => origin);
        return withSessionBranchHistory(
          {
            parentSessionId: sessionId,
            contextDigest: branchContextDigest(branch.messages),
            contextOrigins,
            descriptor: {
              schema: contextEntries.some(
                ({ message, origin }) => message.role === "system" && origin,
              )
                ? BRANCH_HISTORY_SYSTEM_ORIGINS_SCHEMA
                : BRANCH_HISTORY_SCHEMA,
              sourceGeneration: generation,
              totalMessages: count,
              contextMessageCount: contextOrigins.length,
              coverage: { ...coverage },
            },
            visit(visitor) {
              visitSelected(authority, (message, event, index) => {
                visitor({
                  role: message.role,
                  text: transcriptTextParts(message.content).join(""),
                  sourceEventId: event.hash,
                  sourceItemIndex: index,
                });
              });
            },
          },
          branch.consume,
        );
      }
      if (anchor && (!anchored || generation !== anchor.generation))
        throw staleCursor();
      if (needsReplay) {
        // Scan under the same store lock and revalidate the same exact head.
        // Even a rewind into a prefix older than the page buffer stays bounded.
        rows = [];
        bytes = 0;
        incrementalFull = false;
        visitSelected(authority, collect);
      }
      const first = rows[0]?.ordinal ?? 0;
      const snapshot = {
        sessionId,
        generation,
        revision: authority.headHash,
        eventCount: authority.eventCount,
        totalMessages: count,
        messages: rows,
        contextOnly: false,
        coverage,
      };
      const syncCursor = (offset) =>
        Buffer.from(
          JSON.stringify({
            v: 1,
            view: "history-sync",
            sessionId,
            generation,
            revision: authority.headHash,
            eventCount: authority.eventCount,
            offset,
          }),
        ).toString("base64url");
      if (incremental) {
        const nextOffset = rows.length
          ? rows.at(-1).ordinal + 1
          : anchor.offset;
        return {
          schema: CHANGES_SCHEMA,
          ...snapshot,
          from: anchor.offset,
          nextCursor: syncCursor(nextOffset),
          hasMore: nextOffset < count,
        };
      }
      return {
        schema: SCHEMA,
        ...snapshot,
        // Only the latest page establishes an update baseline. Older navigation
        // must not advance it past messages the latest view has not received.
        syncCursor:
          !anchor && authority.eventCount > 0 ? syncCursor(count) : null,
        nextCursor:
          first > 0
            ? Buffer.from(
                JSON.stringify({
                  v: 2,
                  sessionId,
                  generation,
                  revision: authority.headHash,
                  eventCount: authority.eventCount,
                  before: first,
                }),
              ).toString("base64url")
            : null,
      };
    },
  };
}

export function createSessionTranscriptBranchProjection(
  sessionId,
  messages,
  consume,
) {
  if (
    !Array.isArray(messages) ||
    typeof consume !== "function" ||
    consume.constructor?.name === "AsyncFunction"
  )
    throw new TypeError(
      "Branch history requires messages and a synchronous consumer",
    );
  return createSessionTranscriptHistoryProjection(
    sessionId,
    {},
    { messages, consume },
  );
}

export function readSessionTranscriptHistory(sessionId, options = {}) {
  return readVerifiedProjection(sessionId, () =>
    createSessionTranscriptHistoryProjection(sessionId, options),
  );
}

