  BRANCH_HISTORY_MESSAGE,
  BRANCH_HISTORY_ORIGIN,
} from '../src/lib/session-branch-history.js';

// Fork-history ownership regression coverage.
//
// Requirement: two branches each recover valid ancestors (bound to their own
// body by message digest) and independent bodies, and content supplied after
// the branch closes does not leak into the completed archive.
//
// Condition C1 (ancestor ownership): an origin row must reference the branch's
// own body row via a matching digest and an in-range row index.
// Condition C2 (body ownership): a branch's body is bounded by its
// totalMessages; rows beyond that bound do not belong to it.
// Condition C3 (no post-branch leak): events resembling branch content after
// session_branch_complete must not be absorbed into the completed archive.

const hash = (s) =>
  [...s].reduce((h, c) => (Math.imul(31, h) + c.charCodeAt(0)) | 0, 0)
    .toString(16)
    .padStart(64, '0');

// Deterministic 64-hex source ids (event provenance + origin digest target).
const sha2 = (s) => hash(s + ':sha256');

function makeRow(text, i) {
  return {
    type: BRANCH_HISTORY_MESSAGE,
    data: {
      role: 'assistant',
      text,
      part: 0,
      last: true,
      sourceEventId: sha2('src-' + text + '-' + i),
      sourceItemIndex: i,
    },
  };
}

// events: array of already-verified store events to feed the importer in order.
function runImport(descriptor, events) {
  const m = createBranchHistoryImport(descriptor, (chunks) => chunks.join(''));
  const out = [];
  for (const ev of events) {
    const res = m.accept(ev);
    out.push({ kind: res.kind, value: res.value, rejected: res.rejected === true });
    if (res.kind === 'complete') break;
  }
  return out;
}

// bodyText -> branchMessageDigest, mirroring the message digest the origin uses.
const digestOf = (bodyText) => branchMessageDigest({
  role: 'assistant',
  text: bodyText,
  part: 0,
  last: true,
});

describe('fork history ownership (verify-08)', () => {
  const start = { type: 'session_start', data: { sessionId: 's1', language: 'en' } };
  const branch = { type: 'session_branch', data: { branchId: 'b1', fromSessionId: 's1' } };

  // --- Positive control: one branch recovers valid ancestors and its body ---
  it('accepts a branch whose ancestors reference its own body rows and whose body is complete', () => {
    const body1 = makeRow('body-one', 0);
    const body2 = makeRow('body-two', 1);
    const ctxA = { type: 'ctx', data: { role: 'user', text: 'q1', schemaVersion: 2 } };
    const ctxB = { type: 'ctx', data: { role: 'user', text: 'q2', schemaVersion: 2 } };

    const events = [
      start,
      branch,
      body1,
      body2,
      ctxA,
      ctxB,
      {
        type: BRANCH_HISTORY_ORIGIN,
        data: {
          contextMessageIndex: 0,
          first: 0,
          last: 0,
          messageDigest: digestOf('body-one'),
        },
      },
      {
        type: BRANCH_HISTORY_ORIGIN,
        data: {
          contextMessageIndex: 1,
          first: 1,
          last: 1,
          messageDigest: digestOf('body-two'),
        },
      },
      { type: 'session_branch_complete', data: { branchId: 'b1' } },
    ];

    const out = runImport(
      { totalMessages: 2, contextMessageCount: 2, branchId: 'b1', fromSessionId: 's1' },
      events,
    );

    expect(out.at(-1).kind).toBe('complete');
    // The two body rows are preserved in the recovered archive.
    const archive = out.find((r) => r.kind === 'archive')?.value;
    expect(archive).toBeTruthy();
    expect(archive).toHaveProperty('rows');
    expect(archive.rows.map((r) => r.text)).toEqual(['body-one', 'body-two']);
  });

  // --- Positive independence: two forks keep distinct bodies and ancestors ---
  it('keeps two branches fully independent in body and ancestors', () => {
    const branchA = { type: 'session_branch', data: { branchId: 'a', fromSessionId: 's1' } };
    const branchB = { type: 'session_branch', data: { branchId: 'b', fromSessionId: 's1' } };
    const mkRow = (t) => makeRow(t, 0);
    const mkCtx = (t) => ({ type: 'ctx', data: { role: 'user', text: t, schemaVersion: 2 } });
    const mkOrigin = (digest) => ({
      type: BRANCH_HISTORY_ORIGIN,
      data: { contextMessageIndex: 0, first: 0, last: 0, messageDigest: digest },
    });

    const eventsA = [start, branchA, mkRow('alpha-body'), mkCtx('alpha-q'), mkOrigin(digestOf('alpha-body')), { type: 'session_branch_complete', data: { branchId: 'a' } }];
    const eventsB = [start, branchB, mkRow('beta-body'), mkCtx('beta-q'), mkOrigin(digestOf('beta-body')), { type: 'session_branch_complete', data: { branchId: 'b' } }];

    const descA = { totalMessages: 1, contextMessageCount: 1, branchId: 'a', fromSessionId: 's1' };
    const descB = { totalMessages: 1, contextMessageCount: 1, branchId: 'b', fromSessionId: 's1' };

    const outA = runImport(descA, eventsA);
    const outB = runImport(descB, eventsB);

    expect(outA.at(-1).kind).toBe('complete');
    expect(outB.at(-1).kind).toBe('complete');
    const archA = outA.find((r) => r.kind === 'archive')?.value;
    const archB = outB.find((r) => r.kind === 'archive')?.value;
    expect(archA.rows.map((r) => r.text)).toEqual(['alpha-body']);
    expect(archB.rows.map((r) => r.text)).toEqual(['beta-body']);
    // Ancestors are bound to their own body, not the other fork's.
    expect(archA.contexts.map((c) => c.text)).toEqual(['alpha-q']);
    expect(archB.contexts.map((c) => c.text)).toEqual(['beta-q']);
  });

  // --- Negative C1: ancestor digest that does not match the body row ---
  it('rejects an origin whose messageDigest does not match the branch body row', () => {
    const events = [
      start,
      branch,
      makeRow('body-one', 0),
      { type: 'ctx', data: { role: 'user', text: 'q', schemaVersion: 2 } },
      // Wrong digest: references body-one but claims an unrelated hash.
      { type: BRANCH_HISTORY_ORIGIN, data: { contextMessageIndex: 0, first: 0, last: 0, messageDigest: sha2('unrelated') } },
      { type: 'session_branch_complete', data: { branchId: 'b1' } },
    ];
    const out = runImport(
      { totalMessages: 1, contextMessageCount: 1, branchId: 'b1', fromSessionId: 's1' },
      events,
    );
    // The mismatched origin cannot be bound; the import must not complete.
    expect(out.at(-1).kind).not.toBe('complete');
    expect(out.some((r) => r.rejected)).toBe(true);
  });

  // --- Negative C2: a body row beyond totalMessages ---
  it('rejects a branch body row that exceeds the branch totalMessages bound', () => {
    const events = [
      start,
      branch,
      makeRow('body-one', 0),
      makeRow('body-two', 1),
      makeRow('body-three', 2), // third row, but totalMessages is 2
      { type: 'session_branch_complete', data: { branchId: 'b1' } },
    ];
    const out = runImport(
      { totalMessages: 2, contextMessageCount: 0, branchId: 'b1', fromSessionId: 's1' },
      events,
    );
    expect(out.some((r) => r.rejected)).toBe(true);
    expect(out.at(-1).kind).not.toBe('complete');
  });

  // --- Negative C3: stray branch body message after complete ---
  it('rejects a branch body message fed after the branch completed', () => {
    const events = [
      start,
      branch,
      makeRow('body-one', 0),
      { type: 'ctx', data: { role: 'user', text: 'q', schemaVersion: 2 } },
      { type: BRANCH_HISTORY_ORIGIN, data: { contextMessageIndex: 0, first: 0, last: 0, messageDigest: digestOf('body-one') } },
      { type: 'session_branch_complete', data: { branchId: 'b1' } },
      makeRow('stray-body', 1), // arrives after complete
    ];
    const out = runImport(
      { totalMessages: 1, contextMessageCount: 1, branchId: 'b1', fromSessionId: 's1' },
      events,
    );
    // The stray row must be rejected and must not extend the completed archive.
    expect(out.at(-1).rejected).toBe(true);
    const archive = out.find((r) => r.kind === 'archive')?.value;
    expect(archive).toBeTruthy();
    expect(archive.rows.map((r) => r.text)).toEqual(['body-one']);
  });

  // --- Negative C3: stray origin after complete ---
  it('rejects a stray origin event fed after the branch completed', () => {
    const events = [
      start,
      branch,
      makeRow('body-one', 0),
      { type: 'ctx', data: { role: 'user', text: 'q', schemaVersion: 2 } },
      { type: BRANCH_HISTORY_ORIGIN, data: { contextMessageIndex: 0, first: 0, last: 0, messageDigest: digestOf('body-one') } },
      { type: 'session_branch_complete', data: { branchId: 'b1' } },
      { type: BRANCH_HISTORY_ORIGIN, data: { contextMessageIndex: 1, first: 1, last: 1, messageDigest: digestOf('body-one') } },
    ];
    const out = runImport(
      { totalMessages: 1, contextMessageCount: 1, branchId: 'b1', fromSessionId: 's1' },
      events,
    );
    expect(out.at(-1).rejected).toBe(true);
  });
});

