import { describe, it, expect } from 'vitest';
import { createHash } from 'node:crypto';
import {
  createBranchHistoryImport,
  branchMessageDigest,
  BRANCH_HISTORY_SCHEMA,
  BRANCH_HISTORY_MESSAGE,
  BRANCH_HISTORY_ORIGIN,
} from '../src/lib/session-branch-history.js';

// Fork-history ownership regression coverage.
//
// Requirement: two branches each recover valid ancestors (bound to their own
// context by message digest) and independent bodies, and content supplied
// after the branch closes does not leak into the completed archive.
//
// Condition C1 (ancestor ownership): an origin must reference the branch's own
// context via a matching messageDigest and an in-range body row index.
// Condition C2 (body ownership): a branch body is bounded by its
// history.totalMessages; rows beyond that bound do not belong to it.
// Condition C3 (no post-branch leak): events resembling branch content fed
// after session_branch_complete must be rejected and not extend the archive.

// Deterministic 64-lowercase-hex ids (sourceEventId / sourceGeneration).
const hexId = (label, n) => {
  let h = 2166136261;
  const s = label + '|' + n;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0).toString(16).padStart(64, '0');
};

const startEvent = { type: 'session_start', data: { sessionId: 's1', language: 'en' } };

// Build a session_branch event whose history descriptor drives the importer.
function branchEvent(branchId, totalMessages, contextMessageCount) {
  return {
    type: 'session_branch',
    data: {
      branchId,
      fromSessionId: 's1',
      history: {
        schema: BRANCH_HISTORY_SCHEMA,
        sourceGeneration: hexId('gen', 1),
        totalMessages,
        contextMessageCount,
        coverage: { kind: 'from-origin', boundaryEvent: null, reason: null },
      },
    },
  };
}

function rowEvent(text, i) {
  return {
    type: BRANCH_HISTORY_MESSAGE,
    data: {
      role: 'assistant',
      text,
      part: 0,
      last: true,
      sourceEventId: hexId('src-' + text, i),
      sourceItemIndex: i,
    },
  };
}

function contextEvent(text) {
  return { type: 'user_message', data: { role: 'user', content: text } };
}

function originEvent(contextData, first, last) {
  return {
    type: BRANCH_HISTORY_ORIGIN,
    data: {
      messageDigest: branchMessageDigest(contextData),
      origin: { first, last },
    },
  };
}

// Mirror the source digest accumulation so session_branch_complete is valid:
//   sha256("[start,branch, ...", + event rows, "]") -> "sha256:<hex>".
function expectedInputDigest(events) {
  const start = { type: events[0].type, data: { ...events[0].data } };
  const branch = events[1];
  const digest = createHash('sha256').update(
    `[${JSON.stringify(start)},${JSON.stringify({ type: branch.type, data: branch.data })}`,
  );
  for (let i = 2; i < events.length - 1; i++) {
    const ev = events[i];
    digest.update(`,${JSON.stringify({ type: ev.type, data: ev.data })}`);
  }
  digest.update(']');
  return `sha256:${digest.digest('hex')}`;
}

function completeEvent(events, messageCount) {
  return {
    type: 'session_branch_complete',
    data: {
      branchId: events[1].data.branchId,
      schemaVersion: 2,
      messageCount,
      inputDigest: expectedInputDigest(events),
    },
  };
}

// Feed every event; record throw/result per event so negatives can be located.
function feedAll(events) {
  const m = createBranchHistoryImport();
  const out = [];
  for (const ev of events) {
    try {
      const r = m.accept(ev);
      out.push({ threw: false, result: r });
    } catch (error) {
      out.push({ threw: true, error });
      break;
    }
  }
  return out;
}

const rowTexts = (out) =>
  out
    .filter((e) => !e.threw && e.result && e.result.kind === 'archive')
    .map((e) => e.result.message.content);

describe('fork history ownership (verify-08)', () => {
  // --- Positive C1+C2+C3: one branch recovers ancestors and an independent body ---
  it('accepts a branch that recovers valid ancestors and its own complete body', () => {
    const ctx1 = contextEvent('q1');
    const ctx2 = contextEvent('q2');
    const events = [
      startEvent,
      branchEvent('b1', 2, 2),
      rowEvent('body-one', 0),
      rowEvent('body-two', 1),
      ctx1,
      ctx2,
      originEvent(ctx1, 0, 0),
      originEvent(ctx2, 1, 1),
      completeEvent([startEvent, branchEvent('b1', 2, 2), rowEvent('body-one', 0), rowEvent('body-two', 1), ctx1, ctx2, originEvent(ctx1, 0, 0), originEvent(ctx2, 1, 1)], 2),
    ];
    const out = feedAll(events);
    expect(out.at(-1).result.kind).toBe('complete');
    expect(rowTexts(out)).toEqual(['body-one', 'body-two']);
    // Both ancestor origins were accepted and bound to the branch's own contexts.
    const origins = out.filter((e) => !e.threw && e.result && e.result.kind === 'origin');
    expect(origins).toHaveLength(2);
  });

  // --- Positive C2 independence: two forks keep distinct bodies and ancestors ---
  it('keeps two branches fully independent in body and ancestors', () => {
    const ctxA = contextEvent('alpha-q');
    const ctxB = contextEvent('beta-q');
    const baseA = [startEvent, branchEvent('a', 1, 1), rowEvent('alpha-body', 0), ctxA, originEvent(ctxA, 0, 0)];
    const baseB = [startEvent, branchEvent('b', 1, 1), rowEvent('beta-body', 0), ctxB, originEvent(ctxB, 0, 0)];
    const outA = feedAll([...baseA, completeEvent(baseA, 1)]);
    const outB = feedAll([...baseB, completeEvent(baseB, 1)]);
    expect(outA.at(-1).result.kind).toBe('complete');
    expect(outB.at(-1).result.kind).toBe('complete');
    expect(rowTexts(outA)).toEqual(['alpha-body']);
    expect(rowTexts(outB)).toEqual(['beta-body']);
  });

  // --- Negative C1: ancestor origin bound to the wrong context digest ---
  it('rejects an origin whose messageDigest does not match the branch context', () => {
    const ctx = contextEvent('q');
    const events = [
      startEvent,
      branchEvent('b1', 1, 1),
      rowEvent('body-one', 0),
      ctx,
      // messageDigest claims an unrelated context; only this condition is wrong.
      { type: BRANCH_HISTORY_ORIGIN, data: { messageDigest: hexId('unrelated', 0), origin: { first: 0, last: 0 } } },
    ];
    const out = feedAll(events);
    expect(out.at(-1).threw).toBe(true);
    expect(out.at(-1).error.code).toBe('SESSION_BRANCH_HISTORY_INVALID');
  });

  // --- Negative C2: a body row beyond totalMessages ---
  it('rejects a branch body row that exceeds the history totalMessages bound', () => {
    const events = [
      startEvent,
      branchEvent('b1', 2, 0),
      rowEvent('body-one', 0),
      rowEvent('body-two', 1),
      rowEvent('body-three', 2), // third row, but totalMessages is 2
    ];
    const out = feedAll(events);
    expect(out.at(-1).threw).toBe(true);
    expect(out.at(-1).error.code).toBe('SESSION_BRANCH_HISTORY_INVALID');
  });

  // --- Negative C3: stray body message after complete is rejected / not leaked ---
  it('rejects a branch body message fed after the branch completed', () => {
    const ctx = contextEvent('q');
    const base = [startEvent, branchEvent('b1', 1, 1), rowEvent('body-one', 0), ctx, originEvent(ctx, 0, 0)];
    const completed = feedAll([...base, completeEvent(base, 1)]);
    expect(completed.at(-1).result.kind).toBe('complete');
    // Feed a stray body message to the same (now closed) importer state.
    const m = createBranchHistoryImport();
    const baseFeed = feedAll([...base, completeEvent(base, 1)]);
    expect(rowTexts(baseFeed)).toEqual(['body-one']);
    // A fresh importer that already completed must reject post-branch content.
    const fresh = feedAll([...base, completeEvent(base, 1), rowEvent('stray-body', 1)]);
    expect(fresh.at(-1).threw).toBe(true);
    expect(rowTexts(fresh)).toEqual(['body-one']);
    expect(completed).toBeTruthy();
    expect(m).toBeDefined();
  });

  // --- Negative C3: stray origin after complete is rejected ---
  it('rejects a stray origin event fed after the branch completed', () => {
    const ctx = contextEvent('q');
    const base = [startEvent, branchEvent('b1', 1, 1), rowEvent('body-one', 0), ctx, originEvent(ctx, 0, 0)];
    const events = [
      ...base,
      completeEvent(base, 1),
      { type: BRANCH_HISTORY_ORIGIN, data: { messageDigest: branchMessageDigest(ctx), origin: { first: 0, last: 0 } } },
    ];
    const out = feedAll(events);
    expect(out.at(-1).threw).toBe(true);
    expect(out.at(-1).error.code).toBe('SESSION_BRANCH_HISTORY_INVALID');
    expect(rowTexts(out)).toEqual(['body-one']);
  });
});

